  @ffi.Array.multi([4])
  external ffi.Array<ffi.UintPtr> reserved;

  /// < Dav1dFrameHeader allocation origin
  external ffi.Pointer<Dav1dRef> frame_hdr_ref;

  /// < Dav1dSequenceHeader allocation origin
  external ffi.Pointer<Dav1dRef> seq_hdr_ref;

  /// < Dav1dContentLightLevel allocation origin
  external ffi.Pointer<Dav1dRef> content_light_ref;

  /// < Dav1dMasteringDisplay allocation origin
  external ffi.Pointer<Dav1dRef> mastering_display_ref;

  /// < Dav1dITUTT35 allocation origin
  external ffi.Pointer<Dav1dRef> itut_t35_ref;

  /// < reserved for future use
  @ffi.Array.multi([4])
  external ffi.Array<ffi.UintPtr> reserved_ref;

  /// < Frame data allocation origin
  external ffi.Pointer<Dav1dRef> ref;

  /// < pointer managed by the allocator
  external ffi.Pointer<ffi.Void> allocator_data;
